import assert from 'node:assert/strict'
import { spawnSync } from 'node:child_process'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
import { describe, test } from 'vitest'
import { COPY_SURFACES, COPY_LINT_VERSION, copyFields, copyLint } from '../../apps/control-plane/api/_copyLint.js'

// Krish, 2026-10-28: "don't add stupid eyebrow text and asterisks and
// "generated by AI" and "Krish's take" verbal diahorrea like you tend to. This
// needs to feel like a world class media channel". One config, two readers:
// the server's copyLint() and scripts/post-pack/copy_lint.py must give the
// same answer on the same copy, or a session and the server disagree.

const ROOT = join(__dirname, '..', '..')
const PY = process.platform === 'win32' ? 'python' : 'python3'
const read = (rel: string) => readFileSync(join(ROOT, rel), 'utf8')
const config = JSON.parse(read('config/copy-lint.json')) as { version: string; patterns: { id: string; applies_to: string[] }[] }
const examples = JSON.parse(read('tests/fixtures/copy-lint-examples.json')).patterns as Record<string, Record<'hit' | 'pass', { text: string; applies_to: string }[]>>

// The same approved copy tests/copy_lint_test.py holds at zero hits.
const APPROVED = [
  'docs/plans/2026-10-26-monday/cards.json',
  'docs/plans/2026-10-26-monday/cover-facts.json',
  'docs/plans/2026-10-26-monday/cover-facts-wide.json',
  'docs/plans/2026-10-26-monday/creative-direction.json',
  'docs/plans/2026-10-26-monday/post.json',
  'docs/plans/2026-10-19-monday/release-materials.json',
]

const py = (args: string[], input?: string) =>
  spawnSync(PY, args, { cwd: ROOT, encoding: 'utf8', input, env: { ...process.env, PYTHONIOENCODING: 'utf-8' } })

describe('the copy lint (Krish, 2026-10-28)', () => {
  test('the Python tests pass: examples, approved copy and the CLI', () => {
    const r = py(['tests/copy_lint_test.py'])
    assert.equal(r.status, 0, r.stdout + r.stderr)
  }, 120_000)

  test('reads the one config', () => {
    assert.equal(COPY_LINT_VERSION, config.version)
    assert.deepEqual([...COPY_SURFACES].sort(), ['article_metadata', 'carousel_text', 'channel_copy', 'titles', 'video_onscreen'])
  })

  test('every pattern refuses its must-hit copy and lets clean copy through', () => {
    assert.deepEqual(Object.keys(examples).sort(), config.patterns.map((p) => p.id).sort())
    for (const [id, ex] of Object.entries(examples)) {
      assert.ok(ex.hit.length && ex.pass.length, `${id} needs a must-hit and a must-pass example`)
      for (const c of ex.hit) assert.ok(copyLint(c.text, c.applies_to).some((h) => h.id === id), `${id} let through ${JSON.stringify(c.text)}`)
      for (const c of ex.pass) assert.deepEqual(copyLint(c.text, c.applies_to), [], `${id} pass example ${JSON.stringify(c.text)}`)
    }
  })

  test('the server and the Python lint give the same hits at the same places', () => {
    const cases = Object.values(examples).flatMap((ex) => [...ex.hit, ...ex.pass])
    const script = [
      'import json, sys',
      'sys.path.insert(0, "scripts/post-pack")',
      'from copy_lint import copy_lint',
      'cases = json.load(sys.stdin)',
      'print(json.dumps([[[h["id"], h["match"], h["index"]] for h in copy_lint(c["text"], c["applies_to"])] for c in cases]))',
    ].join('\n')
    const r = py(['-c', script], JSON.stringify(cases))
    assert.equal(r.status, 0, r.stderr)
    const python = JSON.parse(r.stdout) as [string, string, number][][]
    cases.forEach((c, i) => {
      assert.deepEqual(copyLint(c.text, c.applies_to).map((h) => [h.id, h.match, h.index]), python[i], JSON.stringify(c))
    })
  })

  test('reads the same public fields as the Python lint, and Monday 26 is clean', () => {
    for (const rel of APPROVED) {
      const data = JSON.parse(read(rel))
      const fields = copyFields(data)
      const r = py(['-c', `import json, sys; sys.path.insert(0, "scripts/post-pack"); from copy_lint import fields; print(json.dumps(fields(json.load(open(${JSON.stringify(rel)}, encoding="utf-8")))))`])
      assert.equal(r.status, 0, r.stderr)
      assert.deepEqual(fields.map((f) => [f.where, f.text, f.appliesTo]), JSON.parse(r.stdout), rel)
      assert.ok(fields.length, rel)
      for (const f of fields) assert.deepEqual(copyLint(f.text, f.appliesTo), [], `${rel} ${f.where}`)
    }
  }, 60_000)

  test('an unknown surface is refused rather than read as clean', () => {
    assert.throws(() => copyLint('**bold**', 'article_body'), /appliesTo must be one of/)
  })
})
